1130.body:
Modifiera Book-klassen så att den har en konstruktor som tar emot titel och författare som argument och sätter egenskaperna. Skapa ett Book-objekt med konstruktorn och anropa displayInfo(). Lösningsförslag <?php
class Book { public string $title; public string $author; public function __construct(string $bookTitle, string $bookAuthor) { $this->title = $bookTitle; $this->author = $bookAuthor; } public function displayInfo(): void { echo "Title: " . $this->title . ", Author: " . $this->author . "\n"; }
} $book = new Book("Liftarens Guide till Galaxen", "Douglas Adams");
