Intervjuare: "Visa hur man implementerar robust felhantering i en PHP-applikation." Bra svar: <?php
// Aktivera strict types och error reporting för utveckling
declare(strict_types=1);
ini_set('display_errors', 1);
error_reporting(E_ALL); // Custom exception klasser
class ValidationException extends Exception {}
class DatabaseException extends Exception {} class UserService { private PDO $pdo; private LoggerInterface $logger; public function createUser(array $userData): int { try { // Validering $this->validateUserData($userData); // Databasoperation $stmt = $this->pdo->prepare( "INSERT INTO users (username, email, password_hash) VALUES (:username, :email, :password)" ); $passwordHash = password_hash($userData['password'], PASSWORD_DEFAULT); $stmt->execute([ ':username' => $userData['username'], ':email' => $userData['email'], ':password' => $passwordHash ]); $userId = (int)$this->pdo->lastInsertId(); $this->logger->info("User created", ['user_id' => $userId]); return $userId; } catch (ValidationException $e) { // Logga validering fel (för utveckling) $this->logger->warning("Validation failed", [ 'error' => $e->getMessage(), 'data' => $userData ]); throw $e; // Re-throw för hantering i controller } catch (PDOException $e) { // Logga databasfel (känslig info) $this->logger->error("Database error creating user", [ 'error' => $e->getMessage(), 'code' => $e->getCode() ]); // Kasta generellt fel till användaren throw new DatabaseException('Could not create user'); } catch (Exception $e) { // Fånga oväntade fel $this->logger->critical("Unexpected error", [ 'error' => $e->getMessage(), 'trace' => $e->getTraceAsString() ]); throw new Exception('An unexpected error occurred'); } } private function validateUserData(array $data): void { if (empty($data['username'])) { throw new ValidationException('Username is required'); } if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL)) { throw new ValidationException('Invalid email format'); } if (strlen($data['password']) < 8) { throw new ValidationException('Password must be at least 8 characters'); } }
} // Global exception handler för produktion
set_exception_handler(function(Throwable $e) { error_log("Uncaught exception: " . $e->getMessage()); // Visa användarvänligt meddelande http_response_code(500); echo "Something went wrong. Please try again later.";
});
?> Förklaring: Använd specifika exceptions, logga tekniska fel separat från användarmeddelanden, och ha en global exception handler som backup.

