function UserProfile({ user }) { return ( <div> <span id="name">{user.name}</span> <span id="age">{user.age}</span> <span id="status">{user.isOnline ? "Online" : "Offline"}</span> {user.isLoggedIn ? ( <UserMenu user={user} /> ) : ( <LoginButton /> )} </div> );
