Context API löser props drilling genom att skapa en "global" state som komponenter kan accessa direkt. import { createContext, useContext, useState } from 'react'; // 1. Skapa Context
const UserContext = createContext(); // 2. Skapa Provider Component
function UserProvider({ children }) { const [user, setUser] = useState({ name: 'Anna', theme: 'light', isAuthenticated: false }); const login = (userData) => { setUser(prev => ({ ...prev, ...userData, isAuthenticated: true })); }; const logout = () => { setUser({ name: '', theme: 'light', isAuthenticated: false }); }; const toggleTheme = () => { setUser(prev => ({ ...prev, theme: prev.theme === 'light' ? 'dark' : 'light' })); }; const value = { user, login, logout, toggleTheme }; return ( <UserContext.Provider value={value}> {children} </UserContext.Provider> );
} // 3. Custom hook för att använda context
function useUser() { const context = useContext(UserContext); if (!context) { throw new Error('useUser must be used within UserProvider'); } return context;
} // 4. Använd Context i komponenter
function App() { return ( <UserProvider> <div className="app"> <Header /> <Main /> <Footer /> </div> </UserProvider> );
} function Header() { return ( <header> <Logo /> <Navigation /> </header> );
} // Ingen props drilling längre!
function Navigation() { const { user, toggleTheme, logout } = useUser(); return ( <nav> <span>Hej {user.name}!</span> <button onClick={toggleTheme}> Tema: {user.theme} </button> {user.isAuthenticated && ( <button onClick={logout}> Logga ut </button> )} </nav> );
} function Main() { const { user } = useUser(); return ( <main className={`theme-${user.theme}`}> {user.isAuthenticated ? ( <Dashboard /> ) : ( <LoginForm /> )} </main> );
} function LoginForm() { const { login } = useUser(); const [formData, setFormData] = useState({ name: '', email: '' }); const handleSubmit = (e) => { e.preventDefault(); login(formData); }; return ( <form onSubmit={handleSubmit}> <input type="text" value={formData.name} onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))} placeholder="Namn" /> <input type="email" value={formData.email} onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))} placeholder="E-post" /> <button type="submit">Logga in</button> </form> );
}

