// Custom hook för formulärhantering
function useForm(initialValues) { const [values, setValues] = useState(initialValues); const [errors, setErrors] = useState({}); const setValue = (name, value) => { setValues(prev => ({ ...prev, [name]: value })); // Rensa fel när användaren rättar if (errors[name]) { setErrors(prev => ({ ...prev, [name]: '' })); } }; const setError = (name, error) => { setErrors(prev => ({ ...prev, [name]: error })); }; const reset = () => { setValues(initialValues); setErrors({}); }; return { values, errors, setValue, setError, reset };
} // Custom hook för localStorage
function useLocalStorage(key, defaultValue) { const [value, setValue] = useState(() => { try { const item = window.localStorage.getItem(key); return item ? JSON.parse(item) : defaultValue; } catch (error) { console.error(`Error reading localStorage key "${key}":`, error); return defaultValue; } }); const setStoredValue = (newValue) => { try { setValue(newValue); window.localStorage.setItem(key, JSON.stringify(newValue)); } catch (error) { console.error(`Error setting localStorage key "${key}":`, error); } }; return [value, setStoredValue];
} // Användning av custom hooks
function UserPreferences() { const { values, setValue, errors, setError } = useForm({ theme: 'light', language: 'sv', notifications: true }); const [settings, setSettings] = useLocalStorage('userSettings', values); const handleSave = () => { if (!values.language) { setError('language', 'Språk är obligatoriskt'); return; } setSettings(values); alert('Inställningar sparade!'); }; return ( <div> <h2>Användarinställningar</h2> <select value={values.theme} onChange={(e) => setValue('theme', e.target.value)} > <option value="light">Ljust tema</option> <option value="dark">Mörkt tema</option> </select> <select value={values.language} onChange={(e) => setValue('language', e.target.value)} > <option value="">Välj språk</option> <option value="sv">Svenska</option> <option value="en">Engelska</option> </select> {errors.language && <span className="error">{errors.language}</span>} <label> <input type="checkbox" checked={values.notifications} onChange={(e) => setValue('notifications', e.target.checked)} /> Aktivera notifikationer </label> <button onClick={handleSave}>Spara inställningar</button> </div> );
