// contexts/AppContext.js - Kombinerad state management
import { createContext, useContext, useReducer, useEffect } from 'react'; const AppContext = createContext(); // Action types
const ACTIONS = { SET_LOADING: 'SET_LOADING', SET_ERROR: 'SET_ERROR', CLEAR_ERROR: 'CLEAR_ERROR', SET_USER: 'SET_USER', SET_PRODUCTS: 'SET_PRODUCTS', ADD_TO_CART: 'ADD_TO_CART', REMOVE_FROM_CART: 'REMOVE_FROM_CART', CLEAR_CART: 'CLEAR_CART', SET_THEME: 'SET_THEME'
}; // Initial state
const initialState = { loading: false, error: null, user: null, products: [], cart: [], theme: 'light'
}; // Reducer function
function appReducer(state, action) { switch (action.type) { case ACTIONS.SET_LOADING: return { ...state, loading: action.payload }; case ACTIONS.SET_ERROR: return { ...state, error: action.payload, loading: false }; case ACTIONS.CLEAR_ERROR: return { ...state, error: null }; case ACTIONS.SET_USER: return { ...state, user: action.payload }; case ACTIONS.SET_PRODUCTS: return { ...state, products: action.payload }; case ACTIONS.ADD_TO_CART: const existingItem = state.cart.find(item => item.id === action.payload.id); if (existingItem) { return { ...state, cart: state.cart.map(item => item.id === action.payload.id ? { ...item, quantity: item.quantity + 1 } : item ) }; } return { ...state, cart: [...state.cart, { ...action.payload, quantity: 1 }] }; case ACTIONS.REMOVE_FROM_CART: return { ...state, cart: state.cart.filter(item => item.id !== action.payload) }; case ACTIONS.CLEAR_CART: return { ...state, cart: [] }; case ACTIONS.SET_THEME: return { ...state, theme: action.payload }; default: return state; }
} // Provider component
export function AppProvider({ children }) { const [state, dispatch] = useReducer(appReducer, initialState); // Load initial data useEffect(() => { const loadInitialData = async () => { try { dispatch({ type: ACTIONS.SET_LOADING, payload: true }); // Load user from localStorage const savedUser = localStorage.getItem('user'); if (savedUser) { dispatch({ type: ACTIONS.SET_USER, payload: JSON.parse(savedUser) }); } // Load theme from localStorage const savedTheme = localStorage.getItem('theme') || 'light'; dispatch({ type: ACTIONS.SET_THEME, payload: savedTheme }); // Load products const response = await fetch('/api/products'); const products = await response.json(); dispatch({ type: ACTIONS.SET_PRODUCTS, payload: products }); } catch (error) { dispatch({ type: ACTIONS.SET_ERROR, payload: error.message }); } finally { dispatch({ type: ACTIONS.SET_LOADING, payload: false }); } }; loadInitialData(); }, []); // Save user to localStorage when it changes useEffect(() => { if (state.user) { localStorage.setItem('user', JSON.stringify(state.user)); } else { localStorage.removeItem('user'); } }, [state.user]); // Save theme to localStorage when it changes useEffect(() => { localStorage.setItem('theme', state.theme); document.documentElement.setAttribute('data-theme', state.theme); }, [state.theme]); // Action creators const actions = { setLoading: (loading) => dispatch({ type: ACTIONS.SET_LOADING, payload: loading }), setError: (error) => dispatch({ type: ACTIONS.SET_ERROR, payload: error }), clearError: () => dispatch({ type: ACTIONS.CLEAR_ERROR }), setUser: (user) => dispatch({ type: ACTIONS.SET_USER, payload: user }), addToCart: (product) => dispatch({ type: ACTIONS.ADD_TO_CART, payload: product }), removeFromCart: (productId) => dispatch({ type: ACTIONS.REMOVE_FROM_CART, payload: productId }), clearCart: () => dispatch({ type: ACTIONS.CLEAR_CART }), toggleTheme: () => { const newTheme = state.theme === 'light' ? 'dark' : 'light'; dispatch({ type: ACTIONS.SET_THEME, payload: newTheme }); } }; return ( <AppContext.Provider value={{ state, actions }}> {children} </AppContext.Provider> );
} // Custom hook
export function useApp() { const context = useContext(AppContext); if (!context) { throw new Error('useApp must be used within AppProvider'); } return context;
}

