class ErrorTracker { static init() { if (process.env.NODE_ENV === 'production') { window.addEventListener('error', this.handleError); window.addEventListener('unhandledrejection', this.handlePromiseRejection); } } static handleError(event) { console.error('Global error:', event.error); // Skicka till error tracking service this.sendToService({ type: 'javascript_error', message: event.error.message, stack: event.error.stack, url: window.location.href, userAgent: navigator.userAgent }); } static handlePromiseRejection(event) { console.error('Unhandled promise rejection:', event.reason); this.sendToService({ type: 'promise_rejection', message: event.reason.toString(), url: window.location.href }); } static sendToService(errorData) { fetch('/api/errors', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(errorData) }).catch(err => console.error('Failed to send error:', err)); }
} export default ErrorTracker;

