Intervjuare: "Vad är skillnaden mellan funktionella och class components? Varför föredras funktionella komponenter idag?" Bra svar: // Class Component (äldre sätt)
class ClassCounter extends React.Component { constructor(props) { super(props); this.state = { count: 0 }; } componentDidMount() { console.log('Component mounted'); } incrementCount = () => { this.setState({ count: this.state.count + 1 }); } render() { return ( <div> <p>Count: {this.state.count}</p> <button onClick={this.incrementCount}>Increment</button> </div> ); }
} // Functional Component med hooks (modernt sätt)
function FunctionalCounter() { const [count, setCount] = useState(0); useEffect(() => { console.log('Component mounted/updated'); }, []); const incrementCount = () => { setCount(count + 1); }; return ( <div> <p>Count: {count}</p> <button onClick={incrementCount}>Increment</button> </div> );
} Fördelar med funktionella komponenter: Enklare syntax och mindre boilerplate-kod Bättre prestanda med hooks Lättare att testa och förstå Modern React development standard

