Intervjuare: "Förklara skillnaden mellan props och state. Visa hur man hanterar props drilling och Context API." Bra svar: // Props - data som skickas från parent till child
function Parent() { const [theme, setTheme] = useState('light'); return ( <Child theme={theme} onThemeChange={setTheme} title="My App" /> );
} function Child({ theme, onThemeChange, title }) { return ( <div className={`app ${theme}`}> <h1>{title}</h1> <button onClick={() => onThemeChange(theme === 'light' ? 'dark' : 'light')}> Toggle Theme </button> </div> );
} // Context API för att undvika props drilling
const ThemeContext = createContext(); function ThemeProvider({ children }) { const [theme, setTheme] = useState('light'); return ( <ThemeContext.Provider value={{ theme, setTheme }}> {children} </ThemeContext.Provider> );
} // Använda context
function ThemedButton() { const { theme, setTheme } = useContext(ThemeContext); return ( <button className={`btn btn-${theme}`} onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} > Current theme: {theme} </button> );
} // App med Context Provider
function App() { return ( <ThemeProvider> <Header /> <Main /> <ThemedButton /> </ThemeProvider> );
} State vs Props: State: Intern data som komponenten äger och kan ändra Props: Data som skickas från föräldrakomponent, read-only

