Intervjuare: "Förklara varför keys är viktiga i React lists och visa best practices." Bra svar: function TodoList() { const [todos, setTodos] = useState([ { id: 1, text: 'Handla mat', completed: false }, { id: 2, text: 'Träna', completed: true }, { id: 3, text: 'Studera React', completed: false } ]); const toggleTodo = (id) => { setTodos(todos.map(todo => todo.id === id ? { ...todo, completed: !todo.completed } : todo )); }; const deleteTodo = (id) => { setTodos(todos.filter(todo => todo.id !== id)); }; return ( <ul> {todos.map(todo => ( <TodoItem key={todo.id} // ✅ Använd stabil, unik key todo={todo} onToggle={toggleTodo} onDelete={deleteTodo} /> ))} </ul> );
} function TodoItem({ todo, onToggle, onDelete }) { return ( <li className={todo.completed ? 'completed' : ''}> <span onClick={() => onToggle(todo.id)}> {todo.text} </span> <button onClick={() => onDelete(todo.id)}> Ta bort </button> </li> );
