Intervjuare: "Skapa en custom hook för API-anrop med loading och error states." Bra svar: // Custom hook för API calls
function useApi(url, options = {}) { const [data, setData] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(null); const refetch = useCallback(async () => { try { setLoading(true); setError(null); const response = await fetch(url, { headers: { 'Content-Type': 'application/json', ...options.headers, }, ...options, }); if (!response.ok) { throw new Error(`HTTP error! status: ${response.status}`); } const result = await response.json(); setData(result); } catch (err) { setError(err.message); } finally { setLoading(false); } }, [url, options]); useEffect(() => { refetch(); }, [refetch]); return { data, loading, error, refetch };
} // Custom hook för forms
function useForm(initialValues, validationRules = {}) { const [values, setValues] = useState(initialValues); const [errors, setErrors] = useState({}); const [touched, setTouched] = useState({}); const handleChange = (name, value) => { setValues(prev => ({ ...prev, [name]: value })); // Validera när användaren ändrar värde if (touched[name] && validationRules[name]) { const error = validationRules[name](value); setErrors(prev => ({ ...prev, [name]: error })); } }; const handleBlur = (name) => { setTouched(prev => ({ ...prev, [name]: true })); // Validera när fält lämnas if (validationRules[name]) { const error = validationRules[name](values[name]); setErrors(prev => ({ ...prev, [name]: error })); } }; const isValid = Object.values(errors).every(error => !error); return { values, errors, touched, handleChange, handleBlur, isValid, setValues, setErrors };
} // Användning av custom hooks
function UsersList() { const { data: users, loading, error, refetch } = useApi('/api/users'); const { values, errors, handleChange, handleBlur, isValid } = useForm( { name: '', email: '' }, { name: (value) => !value ? 'Namn krävs' : '', email: (value) => !/\S+@\S+\.\S+/.test(value) ? 'Ogiltig e-post' : '' } ); if (loading) return <div>Loading users...</div>; if (error) return <div>Error: {error}</div>; return ( <div> <h2>Users</h2> <button onClick={refetch}>Refresh</button> <ul> {users?.map(user => ( <li key={user.id}>{user.name} - {user.email}</li> ))} </ul> <form> <input type="text" placeholder="Name" value={values.name} onChange={(e) => handleChange('name', e.target.value)} onBlur={() => handleBlur('name')} /> {errors.name && <span>{errors.name}</span>} <input type="email" placeholder="Email" value={values.email} onChange={(e) => handleChange('email', e.target.value)} onBlur={() => handleBlur('email')} /> {errors.email && <span>{errors.email}</span>} <button disabled={!isValid}>Add User</button> </form> </div> );
} Fördelar med custom hooks: Återanvändbar logik mellan komponenter Separation of concerns Lättare testning Renare komponentkod

