const ExpensiveComponent = memo(function ExpensiveComponent({ data, onClick }) { console.log('ExpensiveComponent rendered'); return ( <div> <h3>{data.title}</h3> <button onClick={onClick}>Click me</button> </div> );
}); // 2. useMemo för dyra beräkningar
