} // 3. useCallback för att stabilisera funktionsreferenser
function TodoApp() { const [todos, setTodos] = useState([]); // Utan useCallback skapas en ny funktion vid varje render const handleToggleTodo = useCallback((id) => { setTodos(prevTodos => prevTodos.map(todo => todo.id === id ? { ...todo, completed: !todo.completed } : todo ) ); }, []); // Tom dependency array eftersom vi använder functional update const handleDeleteTodo = useCallback((id) => { setTodos(prevTodos => prevTodos.filter(todo => todo.id !== id)); }, []); return ( <div> {todos.map(todo => ( <TodoItem key={todo.id} todo={todo} onToggle={handleToggleTodo} onDelete={handleDeleteTodo} /> ))} </div> );
} // 4. Lazy loading med React.lazy
const LazyDashboard = lazy(() => import('./Dashboard'));
const LazyProfile = lazy(() => import('./Profile')); function App() { return ( <BrowserRouter> <Suspense fallback={<div>Loading...</div>}> <Routes> <Route path="/dashboard" element={<LazyDashboard />} /> <Route path="/profile" element={<LazyProfile />} /> </Routes> </Suspense> </BrowserRouter> );
