import { FixedSizeList as List } from 'react-window'; function VirtualizedList({ items }) { const Row = ({ index, style }) => ( <div style={style}> <div>{items[index].name}</div> </div> ); return ( <List height={600} // Höjd på container itemCount={items.length} itemSize={50} // Höjd per item > {Row} </List> );
