Intervjuare: "Implementera error boundaries och robustfehantering i React." Bra svar: // Error Boundary Class Component
class ErrorBoundary extends React.Component { constructor(props) { super(props); this.state = { hasError: false, error: null, errorInfo: null }; } static getDerivedStateFromError(error) { // Uppdatera state så nästa render visar fallback UI return { hasError: true }; } componentDidCatch(error, errorInfo) { // Logga felet till error reporting service console.error('Error caught by boundary:', error, errorInfo); this.setState({ error: error, errorInfo: errorInfo }); // Skicka till error monitoring (t.ex. Sentry) // errorReportingService.captureException(error); } render() { if (this.state.hasError) { return ( <div className="error-boundary"> <h2>Något gick fel</h2> <details style={{ whiteSpace: 'pre-wrap' }}> {this.state.error && this.state.error.toString()} <br /> {this.state.errorInfo.componentStack} </details> <button onClick={() => window.location.reload()}> Ladda om sidan </button> </div> ); } return this.props.children; }
} // Custom hook för async error handling
function useAsyncError() { const [, setError] = useState(); return useCallback((error) => { setError(() => { throw error; }); }, []);
} // Component med error handling
function UserProfile({ userId }) { const [user, setUser] = useState(null); const [loading, setLoading] = useState(true); const throwAsyncError = useAsyncError(); useEffect(() => { const fetchUser = async () => { try { setLoading(true); const response = await fetch(`/api/users/${userId}`); if (!response.ok) { throw new Error(`Failed to fetch user: ${response.status}`); } const userData = await response.json(); setUser(userData); } catch (error) { // Kasta error till Error Boundary throwAsyncError(error); } finally { setLoading(false); } }; fetchUser(); }, [userId, throwAsyncError]); if (loading) return <div>Loading...</div>; if (!user) return <div>User not found</div>; return ( <div> <h2>{user.name}</h2> <p>{user.email}</p> </div> );
} // App med Error Boundaries
function App() { return ( <ErrorBoundary> <Router> <Header /> <ErrorBoundary> <Routes> <Route path="/user/:id" element={<UserProfile />} /> <Route path="/dashboard" element={ <ErrorBoundary> <Dashboard /> </ErrorBoundary> } /> </Routes> </ErrorBoundary> </Router> </ErrorBoundary> );
} Error handling best practices: Använd Error Boundaries för att fånga rendering errors Implementera graceful degradation Logga fel till monitoring services Visa användarvänliga felmeddelanden Ha fallback UI för kritiska komponenter

