Reducer ger ett deterministiskt sätt att uppdatera state utifrån action → nytt state. Context delar detta state i trädet. När? När flera delar av appen måste läsa/uppdatera samma state och “lyfta state” inte räcker. import { createContext, useContext, useReducer } from 'react'; const AppContext = createContext(); function reducer(state, action) { switch (action.type) { case 'SET_USER': return { ...state, user: action.payload }; default: return state; }
} export function AppProvider({ children }) { const [state, dispatch] = useReducer(reducer, { user: null }); const value = { state, dispatch }; return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
} export function useApp() { const ctx = useContext(AppContext); if (!ctx) throw new Error('useApp must be used within AppProvider'); return ctx;
} Varför? Reducer minskar implicit logik utspridd i många setState‑anrop och gör flöden testbara.

