import { useEffect, useState } from 'react'; class ApiCache { constructor(ttl = 5 * 60 * 1000) { // 5 min this.cache = new Map(); this.ttl = ttl; } set(key, data) { this.cache.set(key, { data, timestamp: Date.now() }); } get(key) { const item = this.cache.get(key); if (!item) return null; if (Date.now() - item.timestamp > this.ttl) { this.cache.delete(key); return null; } return item.data; } clear() { this.cache.clear(); }
} const apiCache = new ApiCache(); export function useCachedApi(key, apiFunction, dependencies = []) { const [data, setData] = useState(() => apiCache.get(key)); const [loading, setLoading] = useState(!data); const [error, setError] = useState(null); useEffect(() => { const fetchData = async () => { const cached = apiCache.get(key); if (cached) { setData(cached); setLoading(false); return; } try { setLoading(true); setError(null); const result = await apiFunction(); apiCache.set(key, result); setData(result); } catch (err) { setError(err.message); } finally { setLoading(false); } }; fetchData(); }, [key, ...dependencies]); return { data, loading, error };
}

