1488.body:
För filuppladdning använder webbläsare multipart/form-data format: ------WebKitFormBoundary7MA4YWxkTrZu0gW
Content-Disposition: form-data; name="image"; filename="photo.jpg"
Content-Type: image/jpeg [BINARY FILE DATA HERE]
------WebKitFormBoundary7MA4YWxkTrZu0gW-- Vi behöver en parser för detta format: function parseMultipartData(body, boundary) { const parts = body.split('--' + boundary); const files = []; const fields = {}; for (const part of parts) { if (part.includes('Content-Disposition')) { const lines = part.split('\r\n'); const dispositionLine = lines.find(line => line.includes('Content-Disposition') ); if (dispositionLine) { const nameMatch = dispositionLine.match(/name="([^"]+)"/); const filenameMatch = dispositionLine.match(/filename="([^"]+)"/); if (filenameMatch && nameMatch) { // Detta är en fil const filename = filenameMatch[1]; const fieldName = nameMatch[1]; const contentTypeIndex = lines.findIndex(line => line.includes('Content-Type') ); const dataStartIndex = contentTypeIndex + 2; const fileData = lines.slice(dataStartIndex, -1).join('\r\n'); files.push({ fieldName, filename, data: fileData }); } } } } return { fields, files };
}

