1512.body:
Låt oss bygga ett komplett Todo API: const express = require('express');
const app = express(); // Middleware
app.use(express.json()); // In-memory data (i verkligheten använd databas)
let todos = [ { id: 1, text: 'Lär dig Express', completed: false }, { id: 2, text: 'Bygg ett API', completed: false }
]; let nextId = 3; // GET alla todos
app.get('/api/todos', (req, res) => { const { completed } = req.query; let filteredTodos = todos; if (completed !== undefined) { const isCompleted = completed === 'true'; filteredTodos = todos.filter(todo => todo.completed === isCompleted); } res.json(filteredTodos);
}); // GET specifik todo
app.get('/api/todos/:id', (req, res) => { const id = parseInt(req.params.id); const todo = todos.find(t => t.id === id); if (!todo) { return res.status(404).json({ error: 'Todo inte hittad' }); } res.json(todo);
}); // POST ny todo
app.post('/api/todos', (req, res) => { const { text } = req.body; if (!text || text.trim().length === 0) { return res.status(400).json({ error: 'Text krävs' }); } const newTodo = { id: nextId++, text: text.trim(), completed: false }; todos.push(newTodo); res.status(201).json(newTodo);
}); // PUT uppdatera todo
app.put('/api/todos/:id', (req, res) => { const id = parseInt(req.params.id); const todoIndex = todos.findIndex(t => t.id === id); if (todoIndex === -1) { return res.status(404).json({ error: 'Todo inte hittad' }); } const { text, completed } = req.body; if (text !== undefined) { if (!text || text.trim().length === 0) { return res.status(400).json({ error: 'Text kan inte vara tom' }); } todos[todoIndex].text = text.trim(); } if (completed !== undefined) { todos[todoIndex].completed = Boolean(completed); } res.json(todos[todoIndex]);
}); // DELETE todo
app.delete('/api/todos/:id', (req, res) => { const id = parseInt(req.params.id); const todoIndex = todos.findIndex(t => t.id === id); if (todoIndex === -1) { return res.status(404).json({ error: 'Todo inte hittad' }); } todos.splice(todoIndex, 1); res.status(204).send();
}); // Error handling
app.use((err, req, res, next) => { console.error(err.stack); res.status(500).json({ error: 'Något gick fel!' });
}); // 404 handler
app.use('*', (req, res) => { res.status(404).json({ error: 'Endpoint finns inte' });
}); const PORT = process.env.PORT || 3000;
app.listen(PORT, () => { console.log(`Todo API körs på port ${PORT}`);
});

