// models/User.js
const userSchema = new Schema({ username: { type: String, required: true, unique: true }, email: { type: String, required: true, unique: true }, password: { type: String, required: true }, profile: { firstName: String, lastName: String, bio: String, avatar: String }, role: { type: String, enum: ['user', 'admin'], default: 'user' }, isActive: { type: Boolean, default: true }, createdAt: { type: Date, default: Date.now }
}); // models/Post.js
const postSchema = new Schema({ title: { type: String, required: true }, content: { type: String, required: true }, excerpt: String, slug: { type: String, unique: true }, author: { type: Schema.Types.ObjectId, ref: 'User', required: true }, categories: [{ type: Schema.Types.ObjectId, ref: 'Category' }], tags: [String], status: { type: String, enum: ['draft', 'published', 'archived'], default: 'draft' }, featured: { type: Boolean, default: false }, publishedAt: Date, createdAt: { type: Date, default: Date.now }, updatedAt: { type: Date, default: Date.now }
}); // Auto-generate slug och excerpt
postSchema.pre('save', function(next) { if (this.isModified('title')) { this.slug = this.title.toLowerCase() .replace(/[^a-z0-9]+/g, '-') .replace(/^-|-$/g, ''); } if (this.isModified('content') && !this.excerpt) { this.excerpt = this.content.substring(0, 150) + '...'; } this.updatedAt = Date.now(); next();
}); // Statisk metod för att hitta publicerade inlägg
postSchema.statics.findPublished = function() { return this.find({ status: 'published' }) .populate('author', 'username profile.firstName profile.lastName') .populate('categories', 'name slug') .sort({ publishedAt: -1 });
}; // Service för blog-operationer
class BlogService { static async createPost(postData, authorId) { const post = new Post({ ...postData, author: authorId }); if (post.status === 'published' && !post.publishedAt) { post.publishedAt = new Date(); } return await post.save(); } static async getPostsWithPagination(page = 1, limit = 10) { const skip = (page - 1) * limit; const [posts, totalCount] = await Promise.all([ Post.findPublished() .skip(skip) .limit(limit), Post.countDocuments({ status: 'published' }) ]); return { posts, pagination: { page, totalPages: Math.ceil(totalCount / limit), totalCount, hasNext: page * limit < totalCount, hasPrev: page > 1 } }; } static async getPostBySlug(slug) { return await Post.findOne({ slug, status: 'published' }) .populate('author', 'username profile') .populate('categories', 'name slug'); }
} module.exports = { User, Post, BlogService }; MongoDB och Mongoose ger dig kraftfulla verktyg för modern datalagring. Dess flexibilitet gör det perfekt för webapplikationer där datakrav utvecklas över tid, medan Mongoose tillhandahåller struktur och säkerhet genom scheman och validering. Nästa steg är att lära dig hur du bygger RESTful API:er som effektivt använder denna datalagring!

