} function createPost(title, content) { if (!title || title.trim().length === 0) { throw new Error('Titel krävs'); } if (!content || content.trim().length === 0) { throw new Error('Innehåll krävs'); } const newPost = { id: nextId++, title: title.trim(), content: content.trim(), createdAt: new Date().toISOString() }; posts.push(newPost); return newPost;
} function updatePost(id, title, content) { const post = getPostById(id); if (title !== undefined) { if (!title || title.trim().length === 0) { throw new Error('Titel kan inte vara tom'); } post.title = title.trim(); } if (content !== undefined) { if (!content || content.trim().length === 0) { throw new Error('Innehåll kan inte vara tomt'); } post.content = content.trim(); } post.updatedAt = new Date().toISOString(); return post;
} function deletePost(id) { const postIndex = posts.findIndex(p => p.id === parseInt(id)); if (postIndex === -1) { throw new Error(`Post med id ${id} hittades inte`); } const deletedPost = posts[postIndex]; posts.splice(postIndex, 1); return deletedPost;
} function resetPosts() { posts = []; nextId = 1;
} export default { getAllPosts, getPostById, createPost, updatePost, deletePost, resetPosts
}; Komplett Post.test.js // models/Post.test.js
