// Async error wrapper
const asyncHandler = (fn) => { return (req, res, next) => { Promise.resolve(fn(req, res, next)).catch(next); };
}; // Global error handler (måste ha 4 parametrar)
const errorHandler = (err, req, res, next) => { let error = { ...err }; error.message = err.message; // Mongoose validation error if (err.name === 'ValidationError') { const message = Object.values(err.errors).map(e => e.message).join(', '); error = { message, statusCode: 400 }; } // Mongoose cast error (invalid ObjectId) if (err.name === 'CastError') { error = { message: 'Resurs inte hittad', statusCode: 404 }; } // Mongoose duplicate key error if (err.code === 11000) { const field = Object.keys(err.keyPattern)[0]; error = { message: `${field} finns redan`, statusCode: 409 }; } // JWT errors if (err.name === 'JsonWebTokenError') { error = { message: 'Ogiltig token', statusCode: 401 }; } if (err.name === 'TokenExpiredError') { error = { message: 'Token har gått ut', statusCode: 401 }; } console.error(err); res.status(error.statusCode || 500).json({ error: error.message || 'Serverfel', ...(process.env.NODE_ENV === 'development' && { stack: err.stack }) });
}; // Använd error handler sist
app.use(errorHandler);

