Autentisering (Authentication) svarar på frågan "Vem är du?" - verifierar användarens identitet. Auktorisation (Authorization) svarar på frågan "Vad får du göra?" - kontrollerar användarens behörigheter. // Autentisering: Verifiera att användaren är inloggad
const authenticate = (req, res, next) => { const token = req.headers.authorization?.split(' ')[1]; if (!token) { return res.status(401).json({ error: 'Token krävs' }); } try { const decoded = jwt.verify(token, process.env.JWT_SECRET); req.user = decoded; next(); } catch (error) { res.status(401).json({ error: 'Ogiltig token' }); }
}; // Auktorisation: Kontrollera att användaren har rätt behörigheter
const authorize = (roles = []) => { return (req, res, next) => { if (!req.user) { return res.status(401).json({ error: 'Inte autentiserad' }); } if (roles.length && !roles.includes(req.user.role)) { return res.status(403).json({ error: 'Otillåten åtkomst' }); } next(); };
}; // Användning
app.get('/api/profile', authenticate, (req, res) => { // Alla inloggade användare
}); app.delete('/api/users/:id', authenticate, authorize(['admin']), (req, res) => { // Endast admins
});

