const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('../models/User'); const JWT_SECRET = process.env.JWT_SECRET;
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '24h'; class AuthController { // Registrera användare static async register(req, res) { try { const { username, email, password, role = 'user' } = req.body; // Kontrollera om användaren redan finns const existingUser = await User.findOne({ $or: [{ email }, { username }] }); if (existingUser) { return res.status(409).json({ error: 'Användare med denna e-post eller användarnamn finns redan' }); } // Hasha lösenord const saltRounds = 12; const hashedPassword = await bcrypt.hash(password, saltRounds); // Skapa användare const user = new User({ username, email, password: hashedPassword, role }); await user.save(); // Skapa JWT token const token = jwt.sign( { id: user._id, email: user.email, role: user.role }, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN } ); // Skicka response utan lösenord const userResponse = { id: user._id, username: user.username, email: user.email, role: user.role }; res.status(201).json({ message: 'Användare skapad framgångsrikt', token, user: userResponse }); } catch (error) { console.error('Registration error:', error); res.status(500).json({ error: 'Kunde inte registrera användare' }); } } // Logga in användare static async login(req, res) { try { const { email, password } = req.body; // Hitta användare (inkludera lösenord för verifiering) const user = await User.findOne({ email }).select('+password'); if (!user) { return res.status(401).json({ error: 'Ogiltiga inloggningsuppgifter' }); } // Kontrollera lösenord const isValidPassword = await bcrypt.compare(password, user.password); if (!isValidPassword) { return res.status(401).json({ error: 'Ogiltiga inloggningsuppgifter' }); } // Kontrollera om kontot är aktivt if (!user.isActive) { return res.status(401).json({ error: 'Kontot är inaktiverat' }); } // Uppdatera senaste inloggning user.lastLogin = new Date(); await user.save(); // Skapa JWT token const token = jwt.sign( { id: user._id, email: user.email, role: user.role }, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN } ); const userResponse = { id: user._id, username: user.username, email: user.email, role: user.role }; res.json({ message: 'Inloggning lyckades', token, user: userResponse }); } catch (error) { console.error('Login error:', error); res.status(500).json({ error: 'Kunde inte logga in' }); } } // Hämta användarens profil static async getProfile(req, res) { try { // req.user kommer från auth middleware const user = await User.findById(req.user.id).select('-password'); if (!user) { return res.status(404).json({ error: 'Användare inte hittad' }); } res.json(user); } catch (error) { res.status(500).json({ error: 'Kunde inte hämta profil' }); } } // Uppdatera lösenord static async changePassword(req, res) { try { const { currentPassword, newPassword } = req.body; const user = await User.findById(req.user.id).select('+password'); // Verifiera nuvarande lösenord const isValidPassword = await bcrypt.compare(currentPassword, user.password); if (!isValidPassword) { return res.status(400).json({ error: 'Felaktigt nuvarande lösenord' }); } // Hasha nytt lösenord const hashedPassword = await bcrypt.hash(newPassword, 12); user.password = hashedPassword; await user.save(); res.json({ message: 'Lösenord uppdaterat framgångsrikt' }); } catch (error) { res.status(500).json({ error: 'Kunde inte uppdatera lösenord' }); } }
} module.exports = AuthController;

