const bcrypt = require('bcrypt');
const crypto = require('crypto'); class PasswordUtils { // Hash lösenord med bcrypt static async hashPassword(password) { const saltRounds = 12; // Högt antal för säkerhet return await bcrypt.hash(password, saltRounds); } // Verifiera lösenord static async verifyPassword(password, hashedPassword) { return await bcrypt.compare(password, hashedPassword); } // Generera säkert random lösenord static generateSecurePassword(length = 12) { const charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*'; let password = ''; for (let i = 0; i < length; i++) { const randomIndex = crypto.randomInt(0, charset.length); password += charset[randomIndex]; } return password; } // Validera lösenordsstyrka static validatePasswordStrength(password) { const minLength = 8; const hasUpperCase = /[A-Z]/.test(password); const hasLowerCase = /[a-z]/.test(password); const hasNumbers = /\d/.test(password); const hasSpecialChars = /[!@#$%^&*(),.?":{}|<>]/.test(password); const errors = []; if (password.length < minLength) { errors.push(`Lösenord måste vara minst ${minLength} tecken`); } if (!hasUpperCase) { errors.push('Lösenord måste innehålla minst en stor bokstav'); } if (!hasLowerCase) { errors.push('Lösenord måste innehålla minst en liten bokstav'); } if (!hasNumbers) { errors.push('Lösenord måste innehålla minst en siffra'); } if (!hasSpecialChars) { errors.push('Lösenord måste innehålla minst ett specialtecken'); } return { isValid: errors.length === 0, errors }; }
}

