const jwt = require('jsonwebtoken');
const crypto = require('crypto'); class JWTUtils { // Skapa token med custom claims static createToken(payload, options = {}) { const defaultOptions = { expiresIn: '15m', // Kort livslängd för access tokens issuer: 'myapp', audience: 'myapp-users' }; return jwt.sign(payload, process.env.JWT_SECRET, { ...defaultOptions, ...options }); } // Skapa refresh token static createRefreshToken() { return crypto.randomBytes(40).toString('hex'); } // Verifiera token static verifyToken(token) { try { return jwt.verify(token, process.env.JWT_SECRET); } catch (error) { throw new Error('Ogiltig eller utgången token'); } } // Blacklist för utloggade tokens static tokenBlacklist = new Set(); static blacklistToken(token) { this.tokenBlacklist.add(token); } static isTokenBlacklisted(token) { return this.tokenBlacklist.has(token); }
} // Förbättrat auth middleware
const authenticateToken = (req, res, next) => { const authHeader = req.headers.authorization; const token = authHeader && authHeader.split(' ')[1]; if (!token) { return res.status(401).json({ error: 'Access token krävs' }); } // Kontrollera blacklist if (JWTUtils.isTokenBlacklisted(token)) { return res.status(401).json({ error: 'Token är ogiltig' }); } try { const decoded = JWTUtils.verifyToken(token); req.user = decoded; req.token = token; // Spara för möjlig blacklisting next(); } catch (error) { res.status(403).json({ error: error.message }); }
};

