// routes/auth.js
const express = require('express');
const router = express.Router();
const AuthController = require('../controllers/AuthController');
const { authenticateToken, authorize } = require('../middleware/auth');
const { validateRegistration, validateLogin } = require('../middleware/validation'); // Publika routes
router.post('/register', validateRegistration, AuthController.register);
router.post('/login', validateLogin, AuthController.login);
router.post('/refresh-token', AuthController.refreshToken);
router.post('/forgot-password', AuthController.forgotPassword);
router.post('/reset-password', AuthController.resetPassword); // Skyddade routes
router.get('/profile', authenticateToken, AuthController.getProfile);
router.put('/profile', authenticateToken, AuthController.updateProfile);
router.put('/change-password', authenticateToken, AuthController.changePassword);
router.post('/logout', authenticateToken, AuthController.logout); // Admin routes
router.get('/users', authenticateToken, authorize(['admin']), AuthController.getAllUsers);
router.put('/users/:id/role', authenticateToken, authorize(['admin']), AuthController.updateUserRole); module.exports = router; // app.js
const authRoutes = require('./routes/auth');
app.use('/api/auth', authRoutes); Middleware och autentisering är grundpelare i säker webbutveckling. Genom att förstå och implementera dessa koncept kan du bygga applikationer som skyddar användardata och säkerställer att endast auktoriserade användare får åtkomst till känslig funktionalitet. Nästa steg är att lära sig om sessionshantering och cookies för mer avancerad användarhantering!

