const bcrypt = require('bcrypt');
const User = require('../models/User'); class SessionAuthController { // Registrera användare static async register(req, res) { try { const { username, email, password } = req.body; // Kontrollera om användaren finns const existingUser = await User.findOne({ $or: [{ email }, { username }] }); if (existingUser) { return res.status(409).json({ error: 'Användare finns redan' }); } // Hasha lösenord const hashedPassword = await bcrypt.hash(password, 12); // Skapa användare const user = new User({ username, email, password: hashedPassword }); await user.save(); // Logga in automatiskt efter registrering req.session.userId = user._id; req.session.user = { id: user._id, username: user.username, email: user.email, role: user.role }; res.status(201).json({ message: 'Användare registrerad och inloggad', user: req.session.user }); } catch (error) { console.error('Registration error:', error); res.status(500).json({ error: 'Registreringsfel' }); } } // Logga in static async login(req, res) { try { const { email, password } = req.body; // Hitta användare const user = await User.findOne({ email }).select('+password'); if (!user) { return res.status(401).json({ error: 'Ogiltiga inloggningsuppgifter' }); } // Verifiera lösenord const isValidPassword = await bcrypt.compare(password, user.password); if (!isValidPassword) { return res.status(401).json({ error: 'Ogiltiga inloggningsuppgifter' }); } // Skapa session req.session.userId = user._id; req.session.user = { id: user._id, username: user.username, email: user.email, role: user.role }; // Uppdatera senaste inloggning user.lastLogin = new Date(); await user.save(); res.json({ message: 'Inloggning lyckades', user: req.session.user }); } catch (error) { console.error('Login error:', error); res.status(500).json({ error: 'Inloggningsfel' }); } } // Logga ut static async logout(req, res) { try { req.session.destroy((err) => { if (err) { return res.status(500).json({ error: 'Kunde inte logga ut' }); } res.clearCookie('sessionId'); res.json({ message: 'Utloggning lyckades' }); }); } catch (error) { res.status(500).json({ error: 'Utloggningsfel' }); } } // Hämta profil static async getProfile(req, res) { try { const user = await User.findById(req.session.userId).select('-password'); if (!user) { return res.status(404).json({ error: 'Användare inte hittad' }); } res.json(user); } catch (error) { res.status(500).json({ error: 'Kunde inte hämta profil' }); } } // Kontrollera session-status static checkSession(req, res) { if (req.session.userId) { res.json({ authenticated: true, user: req.session.user }); } else { res.json({ authenticated: false }); } }
} module.exports = SessionAuthController;

