// Middleware för att kontrollera session-timeout
const sessionTimeout = (timeoutMinutes = 30) => { return (req, res, next) => { if (req.session.userId) { const now = Date.now(); const lastActivity = req.session.lastActivity || now; const timeDiff = now - lastActivity; if (timeDiff > timeoutMinutes * 60 * 1000) { req.session.destroy(); return res.status(401).json({ error: 'Session har gått ut på grund av inaktivitet' }); } // Uppdatera senaste aktivitet req.session.lastActivity = now; } next(); };
}; app.use(sessionTimeout(30)); // 30 minuters timeout

