const crypto = require('crypto'); class SessionEncryption { static encrypt(text, key) { const algorithm = 'aes-256-gcm'; const iv = crypto.randomBytes(16); const cipher = crypto.createCipher(algorithm, key); let encrypted = cipher.update(text, 'utf8', 'hex'); encrypted += cipher.final('hex'); const authTag = cipher.getAuthTag(); return { encrypted, iv: iv.toString('hex'), authTag: authTag.toString('hex') }; } static decrypt(encryptedData, key) { const algorithm = 'aes-256-gcm'; const decipher = crypto.createDecipher(algorithm, key); decipher.setAuthTag(Buffer.from(encryptedData.authTag, 'hex')); let decrypted = decipher.update(encryptedData.encrypted, 'hex', 'utf8'); decrypted += decipher.final('utf8'); return decrypted; }
} // Custom session serialization
app.use(session({ // ... andra inställningar store: new CustomStore({ serialize: (session) => { const key = process.env.SESSION_ENCRYPTION_KEY; const sessionData = JSON.stringify(session); return SessionEncryption.encrypt(sessionData, key); }, deserialize: (encryptedSession) => { const key = process.env.SESSION_ENCRYPTION_KEY; const sessionData = SessionEncryption.decrypt(encryptedSession, key); return JSON.parse(sessionData); } })
}));

