const express = require('express');
const router = express.Router();
const SessionAuthController = require('../controllers/SessionAuthController'); // Middleware för att kontrollera session
const requireAuth = (req, res, next) => { if (!req.session.userId) { return res.status(401).json({ error: 'Inloggning krävs' }); } next();
}; const requireRole = (roles) => { return (req, res, next) => { if (!req.session.user || !roles.includes(req.session.user.role)) { return res.status(403).json({ error: 'Otillåten åtkomst' }); } next(); };
}; // Publika routes
router.post('/register', SessionAuthController.register);
router.post('/login', SessionAuthController.login);
router.get('/session-status', SessionAuthController.checkSession); // Skyddade routes
router.post('/logout', requireAuth, SessionAuthController.logout);
router.get('/profile', requireAuth, SessionAuthController.getProfile);
router.get('/admin', requireAuth, requireRole(['admin']), (req, res) => { res.json({ message: 'Admin-område' });
}); module.exports = router; Sessioner erbjuder en traditionell och säker metod för användarautentisering, särskilt lämplig för traditionella webbapplikationer. Medan JWT är bättre för API:er och mikroservices, ger sessioner bättre kontroll över säkerhet och användarhantering. Nästa steg är att utforska den kompletta demo-applikationen som kombinerar alla dessa koncept!

