}; const authorize = (roles = []) => { return (req, res, next) => { if (!req.user) { return res.status(401).json({ error: 'Autentisering krävs' }); } if (roles.length && !roles.includes(req.user.role)) { return res.status(403).json({ error: 'Otillåten åtkomst' }); } next(); };
}; const optionalAuth = async (req, res, next) => { try { const authHeader = req.headers.authorization; const token = authHeader && authHeader.split(' ')[1]; if (token) { const decoded = jwt.verify(token, process.env.JWT_SECRET); const user = await User.findById(decoded.id); if (user && user.isActive) { req.user = user; } } next(); } catch (error) { // Ignorera fel för optional auth next(); }
