Intervjuare: "Designa ett RESTful API för en produktkatalog och förklara HTTP-metoderna." Bra svar: const express = require('express');
const app = express();
app.use(express.json()); // In-memory data (i verkligheten skulle detta vara en databas)
let products = [ { id: 1, name: 'Laptop', price: 999, category: 'Electronics' }, { id: 2, name: 'Book', price: 19, category: 'Education' }
]; // GET /api/products - Hämta alla produkter
app.get('/api/products', (req, res) => { const { category, minPrice } = req.query; let filtered = products; if (category) { filtered = filtered.filter(p => p.category === category); } if (minPrice) { filtered = filtered.filter(p => p.price >= parseInt(minPrice)); } res.json(filtered);
}); // GET /api/products/:id - Hämta specifik produkt
app.get('/api/products/:id', (req, res) => { const product = products.find(p => p.id === parseInt(req.params.id)); if (!product) { return res.status(404).json({ error: 'Product not found' }); } res.json(product);
}); // POST /api/products - Skapa ny produkt
app.post('/api/products', (req, res) => { const { name, price, category } = req.body; // Validering if (!name || !price || !category) { return res.status(400).json({ error: 'Missing required fields' }); } const newProduct = { id: products.length + 1, name, price: parseFloat(price), category }; products.push(newProduct); res.status(201).json(newProduct);
}); // PUT /api/products/:id - Uppdatera produkt
app.put('/api/products/:id', (req, res) => { const productIndex = products.findIndex(p => p.id === parseInt(req.params.id)); if (productIndex === -1) { return res.status(404).json({ error: 'Product not found' }); } const { name, price, category } = req.body; products[productIndex] = { id: parseInt(req.params.id), name, price: parseFloat(price), category }; res.json(products[productIndex]);
}); // DELETE /api/products/:id - Ta bort produkt
app.delete('/api/products/:id', (req, res) => { const productIndex = products.findIndex(p => p.id === parseInt(req.params.id)); if (productIndex === -1) { return res.status(404).json({ error: 'Product not found' }); } products.splice(productIndex, 1); res.status(204).send(); // No content
}); HTTP-metoder: GET: Hämta data (idempotent) POST: Skapa ny resurs PUT: Uppdatera/ersätt resurs (idempotent) DELETE: Ta bort resurs (idempotent)

