Intervjuare: "Skapa Mongoose-modeller med validering och visa CRUD-operationer." Bra svar: const mongoose = require('mongoose'); // Anslut till MongoDB
mongoose.connect('mongodb://localhost:27017/webshop', { useNewUrlParser: true, useUnifiedTopology: true
}); // Product Schema med validering
const productSchema = new mongoose.Schema({ name: { type: String, required: [true, 'Product name is required'], trim: true, maxlength: [50, 'Name cannot exceed 50 characters'] }, price: { type: Number, required: true, min: [0, 'Price cannot be negative'] }, category: { type: String, required: true, enum: ['Electronics', 'Clothing', 'Books', 'Home'] }, inStock: { type: Boolean, default: true }, tags: [String], createdAt: { type: Date, default: Date.now }
}); // Virtual property (beräknad egenskap)
productSchema.virtual('discountedPrice').get(function() { return this.price * 0.9; // 10% rabatt
}); // Middleware - körs innan sparning
productSchema.pre('save', function(next) { console.log(`Saving product: ${this.name}`); next();
}); const Product = mongoose.model('Product', productSchema); // CRUD Operations med async/await
class ProductService { // Create static async createProduct(productData) { try { const product = new Product(productData); return await product.save(); } catch (error) { throw new Error(`Failed to create product: ${error.message}`); } } // Read static async getAllProducts(filters = {}) { try { const query = {}; if (filters.category) query.category = filters.category; if (filters.inStock !== undefined) query.inStock = filters.inStock; return await Product.find(query) .sort({ createdAt: -1 }) .limit(10); } catch (error) { throw new Error(`Failed to fetch products: ${error.message}`); } } static async getProductById(id) { try { const product = await Product.findById(id); if (!product) throw new Error('Product not found'); return product; } catch (error) { throw error; } } // Update static async updateProduct(id, updateData) { try { const product = await Product.findByIdAndUpdate( id, updateData, { new: true, runValidators: true } ); if (!product) throw new Error('Product not found'); return product; } catch (error) { throw error; } } // Delete static async deleteProduct(id) { try { const product = await Product.findByIdAndDelete(id); if (!product) throw new Error('Product not found'); return product; } catch (error) { throw error; } }
} // Användning i Express routes
app.post('/api/products', async (req, res) => { try { const product = await ProductService.createProduct(req.body); res.status(201).json(product); } catch (error) { res.status(400).json({ error: error.message }); }
}); Förklaring: Mongoose ger schemavalidering, middleware hooks och elegant syntax för MongoDB-operationer.

