Intervjuare: "Implementera JWT-baserad autentisering med middleware för skyddade routes." Bra svar: const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('./models/User'); const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key'; // User registration
app.post('/api/auth/register', async (req, res) => { try { const { username, email, password } = req.body; // Kontrollera om användare redan finns const existingUser = await User.findOne({ email }); if (existingUser) { return res.status(409).json({ error: 'User already exists' }); } // Hasha lösenord const saltRounds = 12; const hashedPassword = await bcrypt.hash(password, saltRounds); // Skapa användare const user = new User({ username, email, password: hashedPassword }); await user.save(); // Skapa JWT token const token = jwt.sign( { userId: user._id, email: user.email }, JWT_SECRET, { expiresIn: '24h' } ); res.status(201).json({ message: 'User created successfully', token, user: { id: user._id, username, email } }); } catch (error) { res.status(500).json({ error: error.message }); }
}); // User login
app.post('/api/auth/login', async (req, res) => { try { const { email, password } = req.body; // Hitta användare const user = await User.findOne({ email }); if (!user) { return res.status(401).json({ error: 'Invalid credentials' }); } // Verifiera lösenord const isValidPassword = await bcrypt.compare(password, user.password); if (!isValidPassword) { return res.status(401).json({ error: 'Invalid credentials' }); } // Skapa JWT token const token = jwt.sign( { userId: user._id, email: user.email }, JWT_SECRET, { expiresIn: '24h' } ); res.json({ message: 'Login successful', token, user: { id: user._id, username: user.username, email: user.email } }); } catch (error) { res.status(500).json({ error: error.message }); }
}); // Authentication middleware
const authenticateToken = (req, res, next) => { const authHeader = req.headers['authorization']; const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN if (!token) { return res.status(401).json({ error: 'Access token required' }); } jwt.verify(token, JWT_SECRET, (err, user) => { if (err) { return res.status(403).json({ error: 'Invalid or expired token' }); } req.user = user; // Lägg till användardatun till request next(); });
}; // Authorization middleware för admin
const authorizeAdmin = async (req, res, next) => { try { const user = await User.findById(req.user.userId); if (!user || user.role !== 'admin') { return res.status(403).json({ error: 'Admin access required' }); } next(); } catch (error) { res.status(500).json({ error: error.message }); }
}; // Skyddade routes
app.get('/api/profile', authenticateToken, async (req, res) => { try { const user = await User.findById(req.user.userId).select('-password'); res.json(user); } catch (error) { res.status(500).json({ error: error.message }); }
}); // Admin-only route
app.delete('/api/admin/users/:id', authenticateToken, authorizeAdmin, async (req, res) => { try { await User.findByIdAndDelete(req.params.id); res.json({ message: 'User deleted successfully' }); } catch (error) { res.status(500).json({ error: error.message }); }
}); Förklaring: JWT innehåller användardata och är självsignerande. Autentisering verifierar vem du är, auktorisation kontrollerar vad du får göra.

