Intervjuare: "Visa hur du implementerar robust felhantering och input-validering i en Express-app." Bra svar: const express = require('express');
const { body, validationResult } = require('express-validator'); // Custom Error class
class AppError extends Error { constructor(message, statusCode) { super(message); this.statusCode = statusCode; this.isOperational = true; Error.captureStackTrace(this, this.constructor); }
} // Validation middleware
const validateProduct = [ body('name') .trim() .isLength({ min: 1, max: 50 }) .withMessage('Name must be between 1-50 characters'), body('price') .isFloat({ min: 0 }) .withMessage('Price must be a positive number'), body('email') .optional() .isEmail() .normalizeEmail() .withMessage('Invalid email format'), body('category') .isIn(['Electronics', 'Clothing', 'Books']) .withMessage('Invalid category')
]; // Check validation results
const handleValidationErrors = (req, res, next) => { const errors = validationResult(req); if (!errors.isEmpty()) { const errorMessages = errors.array().map(error => ({ field: error.param, message: error.msg })); return res.status(400).json({ error: 'Validation failed', details: errorMessages }); } next();
}; // Route med validering
app.post('/api/products', validateProduct, handleValidationErrors, async (req, res, next) => { try { const product = await ProductService.createProduct(req.body); res.status(201).json(product); } catch (error) { next(error); // Skicka till error handler } }
); // Async error handler wrapper
const asyncHandler = (fn) => { return (req, res, next) => { Promise.resolve(fn(req, res, next)).catch(next); };
}; // Användning av async handler
app.get('/api/products/:id', asyncHandler(async (req, res) => { const product = await ProductService.getProductById(req.params.id); if (!product) { throw new AppError('Product not found', 404); } res.json(product);
})); // Global error handling middleware
const globalErrorHandler = (err, req, res, next) => { let error = { ...err }; error.message = err.message; // Mongoose validation error if (err.name === 'ValidationError') { const message = Object.values(err.errors).map(val => val.message).join(', '); error = new AppError(message, 400); } // Mongoose duplicate key error if (err.code === 11000) { const field = Object.keys(err.keyValue)[0]; error = new AppError(`${field} already exists`, 409); } // JWT errors if (err.name === 'JsonWebTokenError') { error = new AppError('Invalid token', 401); } // Log error (i produktion skicka till logging service) console.error(err); res.status(error.statusCode || 500).json({ error: error.message || 'Internal Server Error', timestamp: new Date().toISOString(), path: req.originalUrl, method: req.method, ...(process.NODE_ENV === 'development' && { stack: err.stack }) });
}; app.use(globalErrorHandler); // Handle unhandled promise rejections
process.on('unhandledRejection', (err) => { console.error('Unhandled Promise Rejection:', err); process.exit(1);
}); Förklaring: Strukturerad felhantering med custom error klasser, validering med express-validator och global error middleware för konsekvent felhantering.

