Intervjuare: "Hur optimerar du prestanda i en Node.js-applikation med caching?" Bra svar: const redis = require('redis');
const client = redis.createClient(process.env.REDIS_URL); // Cache middleware
const cache = (duration = 300) => { return async (req, res, next) => { const key = `cache:${req.originalUrl}`; try { const cached = await client.get(key); if (cached) { console.log('Cache hit'); return res.json(JSON.parse(cached)); } // Modifiera res.json för att spara till cache const originalJson = res.json; res.json = function(data) { client.setex(key, duration, JSON.stringify(data)); originalJson.call(this, data); }; next(); } catch (error) { console.error('Cache error:', error); next(); // Fortsätt utan cache vid fel } };
}; // Database query optimization
class ProductService { static async getProductsWithPagination(page = 1, limit = 10, filters = {}) { const skip = (page - 1) * limit; // Bygg query med index const query = {}; if (filters.category) query.category = filters.category; if (filters.priceRange) { query.price = { $gte: filters.priceRange.min, $lte: filters.priceRange.max }; } // Parallel queries för bättre prestanda const [products, totalCount] = await Promise.all([ Product.find(query) .select('name price category') // Välj endast nödvändiga fält .sort({ createdAt: -1 }) .skip(skip) .limit(limit) .lean(), // Returnera plain JavaScript objects Product.countDocuments(query) ]); return { products, pagination: { page, limit, totalPages: Math.ceil(totalCount / limit), totalCount } }; } // Batch operations för bättre prestanda static async createMultipleProducts(productsData) { return await Product.insertMany(productsData, { ordered: false, // Fortsätt även om några misslyckas rawResult: true }); }
} // Routes med cache och prestanda-optimering
app.get('/api/products', cache(300), async (req, res) => { try { const { page, limit, category, minPrice, maxPrice } = req.query; const filters = {}; if (category) filters.category = category; if (minPrice || maxPrice) { filters.priceRange = { min: minPrice ? parseFloat(minPrice) : 0, max: maxPrice ? parseFloat(maxPrice) : Number.MAX_VALUE }; } const result = await ProductService.getProductsWithPagination( parseInt(page) || 1, parseInt(limit) || 10, filters ); res.json(result); } catch (error) { res.status(500).json({ error: error.message }); }
}); // Compression middleware för mindre responses
const compression = require('compression');
app.use(compression()); // Rate limiting för skydd mot överbelastning
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({ windowMs: 15 * 60 * 1000, // 15 minuter max: 100, // Max 100 requests per IP message: 'Too many requests from this IP'
}); app.use('/api/', limiter); // Connection pooling för databas
const mongoose = require('mongoose');
mongoose.connect(config.mongodb.uri, { maxPoolSize: 10, // Maintain up to 10 socket connections serverSelectionTimeoutMS: 5000, // Keep trying to send operations for 5 seconds socketTimeoutMS: 45000, // Close sockets after 45 seconds of inactivity bufferMaxEntries: 0 // Disable mongoose buffering
}); Prestandaoptimering: Redis för caching Database indexing och query optimization Connection pooling Compression och rate limiting Pagination för stora datasets

