 document.createElement('div'); messageElement.classList.add('system-message'); messageElement.textContent = message; messagesContainer.appendChild(messageElement); messagesContainer.scrollTop = messagesContainer.scrollHeight; } setupEventListeners() { document.getElementById('message-form').addEventListener('submit', (e) => { e.preventDefault(); const input = document.getElementById('message-input'); const message = input.value.trim(); if (message) { this.sendChatMessage(message); input.value = ''; } }); }
