class Player extends Character { constructor(x, y) { super(x, y, 32, 32, 100); this.score = 0; this.lives = 3; this.weapons = ['pistol']; this.currentWeapon = 0; this.ammunition = { pistol: Infinity, rifle: 30 }; } onDeath() { this.lives--; if (this.lives > 0) { this.respawn(); } else { this.gameOver(); } } respawn() { this.health = this.maxHealth; this.x = 100; // Startposition this.y = 100; this.isDead = false; } shoot() { const weapon = this.weapons[this.currentWeapon]; const ammo = this.ammunition[weapon]; if (ammo > 0) { // Skapa projektil const bullet = new PlayerBullet( this.x + this.width / 2, this.y, this.direction ); game.addEntity(bullet); if (ammo !== Infinity) { this.ammunition[weapon]--; } } } switchWeapon() { this.currentWeapon = (this.currentWeapon + 1) % this.weapons.length; }
} // Fiendeklass
class Enemy extends Character { constructor(x, y, health, aiType = 'basic') { super(x, y, 24, 24, health); this.aiType = aiType; this.attackDamage = 10; this.scoreValue = 100; this.lastAttack = 0; this.attackCooldown = 1000; // ms } update(deltaTime) { super.update(deltaTime); this.updateAI(deltaTime); this.checkAttack(); } updateAI(deltaTime) { switch (this.aiType) { case 'basic': this.basicAI(deltaTime); break; case 'aggressive': this.aggressiveAI(deltaTime); break; case 'defensive': this.defensiveAI(deltaTime); break; } } basicAI(deltaTime) { // Enkel AI: rör sig mot spelaren const player = game.getPlayer(); if (player) { const dx = player.x - this.x; const dy = player.y - this.y; const distance = Math.sqrt(dx * dx + dy * dy); if (distance > 0) { this.velocity.x = (dx / distance) * 50; // Hastighet 50 px/s this.velocity.y = (dy / distance) * 50; } } } checkAttack() { const now = Date.now(); if (now - this.lastAttack < this.attackCooldown) return; const player = game.getPlayer(); if (player && this.collidesWith(player)) { player.takeDamage(this.attackDamage); this.lastAttack = now; } } onDeath() { // Ge poäng till spelaren const player = game.getPlayer(); if (player) { player.score += this.scoreValue; } // Möjlighet att droppa items this.dropLoot(); } dropLoot() { if (Math.random() < 0.3) { // 30% chans const powerup = new HealthPowerUp(this.x, this.y); game.addEntity(powerup); } }
}

