Mål : Implementera enkel AI-beteende Instruktioner : Skapa en Enemy-klass som ärver från GameObject. I konstruktorn ska den ta emot x, y och ett target-objekt (t.ex. en Player-instans). Lägg till en speed-egenskap (t.ex. 50 pixlar per sekund). Överskriv update-metoden så att fienden automatiskt rör sig mot target-objektet. Beräkna riktningen genom att hitta skillnaden i x- och y-koordinater mellan fienden och målet. Normalisera riktningsvektorn genom att dividera med avståndet (använd Pythagoras sats för att beräkna avståndet). Multiplicera den normaliserade riktningen med speed och deltaTime (konverterat till sekunder) för att uppdatera fiendens position. Överskriv render-metoden så att fienden ritas som en röd rektangel. I game loopen ska fienden uppdateras med deltaTime varje frame. Lösningsförslag class Enemy extends GameObject { constructor(x, y, target) { super(x, y, 30, 30); this.target = target; this.speed = 50; // pixels per sekund } update(deltaTime) { if (!this.target) return; const dt = deltaTime / 1000; // konvertera till sekunder // Beräkna riktning mot målet const dx = this.target.x - this.x; const dy = this.target.y - this.y; const distance = Math.sqrt(dx * dx + dy * dy); if (distance > 0) { // Normalisera och multiplicera med hastighet this.x += (dx / distance) * this.speed * dt; this.y += (dy / distance) * this.speed * dt; } } render(ctx) { ctx.fillStyle = 'red'; ctx.fillRect(this.x, this.y, this.width, this.height); }
} // Användning i game loop
let lastTime = 0;
function gameLoop(currentTime) { const deltaTime = currentTime - lastTime; lastTime = currentTime; enemy.update(deltaTime); enemy.render(ctx); requestAnimationFrame(gameLoop);
}

