<head> <title>Chat med Användarnamn</title>
</head>
<body> <div id="login"> <input type="text" id="usernameInput" placeholder="Ange ditt namn..."> <button id="connectBtn">Anslut</button> </div> <div id="chat" style="display: none;"> <div id="messages"></div> <form id="messageForm"> <input type="text" id="messageInput" placeholder="Skriv ett meddelande..."> <button type="submit">Skicka</button> </form> </div> <script> let socket = null; let username = ''; const loginDiv = document.getElementById('login'); const chatDiv = document.getElementById('chat'); const usernameInput = document.getElementById('usernameInput'); const connectBtn = document.getElementById('connectBtn'); const messagesDiv = document.getElementById('messages'); const messageForm = document.getElementById('messageForm'); const messageInput = document.getElementById('messageInput'); connectBtn.addEventListener('click', () => { username = usernameInput.value.trim(); if (username) { socket = new WebSocket('ws://localhost:3000'); socket.onopen = () => { // Skicka användarnamn till servern socket.send(JSON.stringify({ type: 'setUsername', username: username })); loginDiv.style.display = 'none'; chatDiv.style.display = 'block'; }; socket.onmessage = (event) => { const data = JSON.parse(event.data); const message = document.createElement('div'); message.innerHTML = `<strong>${data.username}:</strong> ${data.message}`; messagesDiv.appendChild(message); }; } }); messageForm.addEventListener('submit', (e) => { e.preventDefault(); if (socket && socket.readyState === WebSocket.OPEN && messageInput.value) { socket.send(JSON.stringify({ type: 'message', message: messageInput.value })); messageInput.value = ''; } }); </script>
</body>
</html> Server-side (Node.js) : // server.js
const express = require('express');
const http = require('http');
const WebSocket = require('ws'); const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server }); app.use(express.static('public')); wss.on('connection', (ws) => { let username = 'Anonym'; ws.on('message', (message) => { try { const data = JSON.parse(message); if (data.type === 'setUsername') { username = data.username; ws.send(JSON.stringify({ type: 'system', message: `Välkommen, ${username}!` })); } else if (data.type === 'message') { // Broadcast till alla klienter const broadcastData = { type: 'message', username: username, message: data.message }; wss.clients.forEach((client) => { if (client.readyState === WebSocket.OPEN) { client.send(JSON.stringify(broadcastData)); } }); } } catch (error) { console.error('Error parsing message:', error); } }); ws.on('close', () => { console.log(`${username} kopplade från`); });
}); server.listen(3000, () => { console.log('Server körs på port 3000');
});

