@use laddar en fil och gör dess innehål tillgängligt med ett namespace. // abstracts/_variables.scss
$primary-color: #007aff;
$radius-md: 0.5rem; // components/_button.scss
@use '../abstracts/variables' as v; .button { background: v.$primary-color; // Måste använda namespace v.$ border-radius: v.$radius-md;
