Skapa en enkel kalkylator med funktioner. Skapa funktioner för de fyra räknesätten: add, subtract, multiply, divide. Skapa sedan en funktion calculate som tar tre parametrar: två tal och en operator (som sträng, t.ex. "+", "-", "*", "/") och använder rätt funktion baserat på operatorn. // Skriv dina funktioner här
console.log(calculate(10, 5, "+")); // Ska skriva ut: 15
console.log(calculate(10, 5, "-")); // Ska skriva ut: 5
console.log(calculate(10, 5, "*")); // Ska skriva ut: 50
console.log(calculate(10, 5, "/")); // Ska skriva ut: 2 Lösningsförslag const add = (a, b) => a + b;
const subtract = (a, b) => a - b;
const multiply = (a, b) => a * b;
const divide = (a, b) => a / b; function calculate(a, b, operator) { if (operator === "+") { return add(a, b); } else if (operator === "-") { return subtract(a, b); } else if (operator === "*") { return multiply(a, b); } else if (operator === "/") { return divide(a, b); } else { return "Okänd operator"; }
} console.log(calculate(10, 5, "+")); // Skriver ut: 15
console.log(calculate(10, 5, "-")); // Skriver ut: 5
console.log(calculate(10, 5, "*")); // Skriver ut: 50
console.log(calculate(10, 5, "/")); // Skriver ut: 2 Alternativ med switch: function calculate(a, b, operator) { switch (operator) { case "+": return add(a, b); case "-": return subtract(a, b); case "*": return multiply(a, b); case "/": return divide(a, b); default: return "Okänd operator"; }
}

