function findMax(numbers) { // Startar med första talet i arrayen som största hittills let max = numbers[0]; // Loopar igenom alla tal i arrayen (börjar på index 1 eftersom vi redan har index 0) for (let i = 1; i < numbers.length; i++) { // Kontrollerar om det aktuella talet är större än max if (numbers[i] > max) { // Om det är större, uppdatera max till det nya värdet max = numbers[i]; } } // Returnera det största talet return max;
} // Testar funktionen
let result = findMax([3, 7, 2, 9, 1, 5]);
console.log(result); // Skriver ut: 9 // Ytterligare exempel:
console.log(findMax([1, 5, 3])); // Skriver ut: 5
console.log(findMax([-5, -2, -10])); // Skriver ut: -2 Förklaring: Funktionen tar en array med tal som parameter let max = numbers[0] startar med första talet som största hittills Loopen går igenom resten av arrayen (från index 1) if (numbers[i] > max) kontrollerar om det aktuella talet är större Om det är större, uppdateras max till det nya värdet Efter loopen returneras det största talet som hittades Algoritmen jämför varje tal med det största hittills och uppdaterar vid behov

