function fetchUserData(userId) { return fetch(`/api/users/${userId}`) .then(response => response.json()) .then(user => fetch(`/api/posts?userId=${user.id}`)) .then(response => response.json()) .then(posts => ({ user, posts })) .catch(error => console.error("Error:", error));
} Förslag till svar: // Async/Await version
