// Version B: 1 sekund total // Promise.all() alternativ och felhantering
async function robustFetch() { try { // Promise.all - misslyckas om EN request misslyckas const results = await Promise.all([...]); // Promise.allSettled - fortsätter även om några misslyckas const results2 = await Promise.allSettled([...]); results2.forEach((result, index) => { if (result.status === 'fulfilled') { console.log(`Request ${index}:`, result.value); } else { console.error(`Request ${index} failed:`, result.reason); } }); } catch (error) { console.error("At least one request failed:", error); }
