Fråga: "Du får detta fel i konsolen: 'TypeError: Cannot read property 'map' of undefined'. Hur skulle du debugga och fixa problemet i denna kod?" async function displayUsers() { try { const response = await fetch('/api/users'); const data = await response.json(); const userList = data.users.map(user => `<li>${user.name}</li>`); document.getElementById('user-list').innerHTML = userList.join(''); } catch (error) { console.error("Error:", error); }
} Förslag till svar: Problemanalys: data.users är undefined när .map() anropas API:et kanske returnerar olika struktur än förväntat Nätverksfel kan ge oväntad response Debug-teknik: async function displayUsers() { try { const response = await fetch('/api/users'); // Debug 1: Kontrollera response status console.log('Response status:', response.status); if (!response.ok) { throw new Error(`HTTP Error: ${response.status}`); } const data = await response.json(); // Debug 2: Logga faktisk data-struktur console.log('Received data:', data); console.log('Data type:', typeof data); console.log('Has users property:', 'users' in data); // Defensive programming - kontrollera innan map if (!data || !Array.isArray(data.users)) { console.warn('Unexpected data structure:', data); // Fallback för olika API-strukturer const users = Array.isArray(data) ? data : []; return displayUsersFallback(users); } const userList = data.users.map(user => { // Debug 3: Kontrollera varje user-objekt if (!user || !user.name) { console.warn('Invalid user object:', user); return '<li>Unknown user</li>'; } return `<li>${user.name}</li>`; }); const listElement = document.getElementById('user-list'); if (listElement) { listElement.innerHTML = userList.join(''); } else { console.error('Element with id "user-list" not found'); } } catch (error) { console.error("Error in displayUsers:", error); // Visa user-friendly meddelande const listElement = document.getElementById('user-list'); if (listElement) { listElement.innerHTML = '<li>Failed to load users</li>'; } }
} function displayUsersFallback(users) { // Hantera alternativ data-struktur console.log('Using fallback for users:', users);
} Best Practices: Logga intermediate steps för att förstå data-flöde Defensive programming - kontrollera data-typer Graceful degradation - visa fallback vid fel User-friendly error messages - inte bara console.error

