wp_enqueue_style() och wp_enqueue_script() är WordPress sätt att ladda filer på rätt sätt. Fördelar: undviker dubbel inladdning bättre kompatibilitet med andra teman/plugins WordPress kan hantera ordning och beroenden Skapa assets/slider.css: .school-slider { position: relative; overflow: hidden; min-height: 380px;
} .school-slider__track { position: relative;
} .school-slide { display: none; min-height: 380px; background-size: cover; background-position: center;
} .school-slide.is-active { display: block;
} .school-slide__overlay { background: rgba(0, 0, 0, 0.45); color: #fff; padding: 64px 40px; min-height: 380px; display: flex; flex-direction: column; justify-content: center; gap: 12px;
} .school-slide__title { margin: 0; font-size: 2rem;
} .school-slide__subtitle { margin: 0; font-size: 1.1rem;
} .school-slide__button { align-self: flex-start; padding: 10px 18px; background: #ffffff; color: #111111; text-decoration: none; border-radius: 6px;
} .school-slider__nav { position: absolute; top: 50%; transform: translateY(-50%); background: rgba(0, 0, 0, 0.55); color: #ffffff; border: 0; width: 42px; height: 42px; border-radius: 50%; cursor: pointer; font-size: 1.2rem; z-index: 10;
} .school-slider__nav--prev { left: 16px;
} .school-slider__nav--next { right: 16px;
} .school-slider__dots { position: absolute; left: 50%; bottom: 18px; transform: translateX(-50%); display: flex; gap: 8px; z-index: 10;
} .school-slider__dot { width: 10px; height: 10px; border-radius: 50%; border: 0; background: rgba(255, 255, 255, 0.5); cursor: pointer;
} .school-slider__dot.is-active { background: #ffffff;
} Skapa assets/slider.js: document.addEventListener('DOMContentLoaded', () => { const sliders = document.querySelectorAll('[data-slider]'); if (!sliders.length) { return; } sliders.forEach((slider) => { const slides = Array.from(slider.querySelectorAll('.school-slide')); const dots = Array.from(slider.querySelectorAll('.school-slider__dot')); const prevButton = slider.querySelector('[data-slider-prev]'); const nextButton = slider.querySelector('[data-slider-next]'); if (!slides.length) { return; } let activeIndex = 0; const render = () => { slides.forEach((slide, index) => { slide.classList.toggle('is-active', index === activeIndex); }); dots.forEach((dot, index) => { dot.classList.toggle('is-active', index === activeIndex); }); }; const goToNext = () => { activeIndex = (activeIndex + 1) % slides.length; render(); }; const goToPrev = () => { activeIndex = (activeIndex - 1 + slides.length) % slides.length; render(); }; if (nextButton) { nextButton.addEventListener('click', goToNext); } if (prevButton) { prevButton.addEventListener('click', goToPrev); } dots.forEach((dot) => { dot.addEventListener('click', () => { activeIndex = Number(dot.dataset.slideTo); render(); }); }); render(); setInterval(goToNext, 5000); });
});

