if ($_SERVER['REQUEST_METHOD'] === 'POST') { $username = trim($_POST['username'] ?? ''); $email = trim($_POST['email'] ?? ''); $password = $_POST['password'] ?? ''; $confirm_password = $_POST['confirm_password'] ?? ''; // Validering kommer i nästa steg – för nu försöker vi bara spara if (true) { // Tillfälligt – vi byter ut detta mot validering senare try { $pdo = connect_db(); // VIKTIGT: Hasha lösenordet – lagra ALDRIG lösenord i klartext! $password_hash = password_hash($password, PASSWORD_DEFAULT); $stmt = $pdo->prepare("INSERT INTO users (username, email, password_hash) VALUES (:username, :email, :password_hash)"); $stmt->bindParam(':username', $username); $stmt->bindParam(':email', $email); $stmt->bindParam(':password_hash', $password_hash); if ($stmt->execute()) { header('Location: login.php?registered=success'); exit; } else { $errors[] = 'Ett fel uppstod vid registrering. Försök igen.'; } } catch (PDOException $e) { error_log("Registration Error: " . $e->getMessage()); $errors[] = 'Databasfel. Kan inte registrera användare just nu.'; } }
