Om $stmt->execute() eller databasen misslyckas efter att vi redan flyttat en ny bild till uploads/, måste vi ta bort den filen. Annars blir det kvar "förlorade" filer. Lägg till variabeln $image_uploaded = true när en ny bild sparas, och i else-grenarna (där vi sätter $errors[]) efter $stmt->execute(): if ($image_uploaded && $new_image_path && file_exists(UPLOAD_PATH . basename($new_image_path))) { unlink(UPLOAD_PATH . basename($new_image_path));
} Hela POST-blocket med alla tre delar sammansatt: if ($_SERVER['REQUEST_METHOD'] === 'POST' && $post) { $title = trim($_POST['title'] ?? ''); $body = trim($_POST['body'] ?? ''); $image = $_FILES['image'] ?? null; $delete_image = isset($_POST['delete_image']); $new_image_path = $current_image_path; $image_uploaded = false; if (empty($title)) { $errors[] = 'Titel är obligatoriskt.'; } if (empty($body)) { $errors[] = 'Innehåll är obligatoriskt.'; } if ($delete_image) { if ($current_image_path && file_exists(UPLOAD_PATH . basename($current_image_path))) { unlink(UPLOAD_PATH . basename($current_image_path)); } $new_image_path = null; $current_image_path = null; } elseif ($image && $image['error'] === UPLOAD_ERR_OK) { $allowed_types = ['image/jpeg', 'image/png', 'image/gif']; $max_size = 5 * 1024 * 1024; if (!in_array($image['type'], $allowed_types)) { $errors[] = 'Ogiltig filtyp. Endast JPG, PNG och GIF.'; } elseif ($image['size'] > $max_size) { $errors[] = 'Filen är för stor. Max 5 MB.'; } else { $file_extension = pathinfo($image['name'], PATHINFO_EXTENSION); $unique_filename = uniqid('post_img_', true) . '.' . $file_extension; $destination = UPLOAD_PATH . $unique_filename; if (move_uploaded_file($image['tmp_name'], $destination)) { if ($current_image_path && file_exists(UPLOAD_PATH . basename($current_image_path))) { unlink(UPLOAD_PATH . basename($current_image_path)); } $new_image_path = 'uploads/' . $unique_filename; $image_uploaded = true; } else { $errors[] = 'Kunde inte ladda upp den nya bilden.'; } } } if (empty($errors)) { try { $post_model = new Post(connect_db()); if ($post_model->updateOne($post_id, $logged_in_user_id, $title, $body, $new_image_path)) { header('Location: index.php?updated=success&id=' . $post_id); exit; } else { $errors[] = 'Ett fel uppstod när inlägget skulle uppdateras.'; if ($image_uploaded && $new_image_path && file_exists(UPLOAD_PATH . basename($new_image_path))) { unlink(UPLOAD_PATH . basename($new_image_path)); } } } catch (PDOException $e) { error_log("Update Post Error: " . $e->getMessage()); $errors[] = 'Databasfel. Kan inte uppdatera inlägg just nu.'; if ($image_uploaded && $new_image_path && file_exists(UPLOAD_PATH . basename($new_image_path))) { unlink(UPLOAD_PATH . basename($new_image_path)); } } }
} Redigera inlägg med bildhantering – visa nuvarande bild, ta bort eller ersätta Du har nu lärt dig: Att hantera tre fall – behålla bild, ta bort bild, ersätta bild – och att städa upp filer om databasen misslyckas.

