Skapa admin/delete_post.php: <?php
require_once '../includes/config.php'; if (!isset($_SESSION['user_id'])) { header('Location: ../login.php'); exit;
}
$logged_in_user_id = $_SESSION['user_id']; require_once '../includes/database.php';
require_once '../includes/Post.php'; $errors = []; if ($_SERVER['REQUEST_METHOD'] === 'POST') { $post_id = filter_input(INPUT_POST, 'post_id', FILTER_VALIDATE_INT); if ($post_id === false || $post_id <= 0) { $errors[] = "Ogiltigt inläggs-ID."; } else { try { $pdo = connect_db(); $post_model = new Post($pdo); $post_data = $post_model->showOne($post_id); if (!$post_data) { $errors[] = "Inlägget hittades inte."; } elseif ($post_data['user_id'] != $logged_in_user_id) { $errors[] = "Du har inte behörighet att radera detta inlägg."; } else { if ($post_model->deleteOne($post_id, $logged_in_user_id)) { $image_to_delete = $post_data['image_path']; if ($image_to_delete && file_exists(UPLOAD_PATH . basename($image_to_delete))) { unlink(UPLOAD_PATH . basename($image_to_delete)); } header('Location: index.php?deleted=success&id=' . $post_id); exit; } else { $errors[] = "Kunde inte radera inlägget."; } } } catch (PDOException $e) { error_log("Delete Post Error: " . $e->getMessage()); $errors[] = 'Databasfel. Kan inte radera inlägg just nu.'; } }
} else { $errors[] = "Ogiltig förfrågan. Radering kräver POST.";
}
?>
